INSERT INTO public.site_content (section, mode, field, value) VALUES ('about', 'thor', 'panel1Kicker', '"THE BEGINNING"'::jsonb) ON CONFLICT (section, mode, field) DO NOTHING;
INSERT INTO public.site_content (section, mode, field, value) VALUES ('about', 'thor', 'panel1Caption', '"Every hero has an origin. Mine had a blinking cursor."'::jsonb) ON CONFLICT (section, mode, field) DO NOTHING;
INSERT INTO public.site_content (section, mode, field, value) VALUES ('about', 'thor', 'panel1Body1', '"One line of code. Hello, world. A question I couldn’t unhear: \"What if I could make the screen do anything?\" Whosoever holds that question, if they be patient enough, shall possess the power."'::jsonb) ON CONFLICT (section, mode, field) DO NOTHING;
INSERT INTO public.site_content (section, mode, field, value) VALUES ('about', 'thor', 'panel1Body2', '"From scrappy HTML pages to full-stack apps shipping to real users — the obsession never changed, only the tools. The dream was always to build something people love to use."'::jsonb) ON CONFLICT (section, mode, field) DO NOTHING;
INSERT INTO public.site_content (section, mode, field, value) VALUES ('about', 'thor', 'panel2Kicker', '"THE TRAINING MONTAGE"'::jsonb) ON CONFLICT (section, mode, field) DO NOTHING;
INSERT INTO public.site_content (section, mode, field, value) VALUES ('about', 'thor', 'panel2Caption', '"Mt. Colubo was a metaphor. The grind was real."'::jsonb) ON CONFLICT (section, mode, field) DO NOTHING;
INSERT INTO public.site_content (section, mode, field, value) VALUES ('about', 'thor', 'panel2Body1', '"React, TypeScript, Node, then deeper — Postgres internals, GLSL shaders, accessibility specs at 2 AM. Every framework a new gear. Every paradigm a new transformation. Gear 2 was speed. Gear 3 was scale."'::jsonb) ON CONFLICT (section, mode, field) DO NOTHING;
INSERT INTO public.site_content (section, mode, field, value) VALUES ('about', 'thor', 'panel2Body2', '"Then the LLM wave hit. RAG pipelines, agent orchestration, evals, vector search. Gear 4 unlocked. Suddenly the screen could think back."'::jsonb) ON CONFLICT (section, mode, field) DO NOTHING;
INSERT INTO public.site_content (section, mode, field, value) VALUES ('about', 'thor', 'panel3Kicker', '"THE FIRST BATTLE"'::jsonb) ON CONFLICT (section, mode, field) DO NOTHING;
INSERT INTO public.site_content (section, mode, field, value) VALUES ('about', 'thor', 'panel3Caption', '"Production. Real users. No respawn."'::jsonb) ON CONFLICT (section, mode, field) DO NOTHING;
INSERT INTO public.site_content (section, mode, field, value) VALUES ('about', 'thor', 'panel3Body1', '"First feature in front of real users — a real-time collab layer that had to work on day one. It did. Then a 3 AM page: a query timeout under load. Welcome to production. Welcome to the Grand Line."'::jsonb) ON CONFLICT (section, mode, field) DO NOTHING;
INSERT INTO public.site_content (section, mode, field, value) VALUES ('about', 'thor', 'panel3Body2', '"Lesson learned: performance is a feature, error states are first-class citizens, and every screen deserves a keyboard. Mjolnir doesn’t fly itself."'::jsonb) ON CONFLICT (section, mode, field) DO NOTHING;
INSERT INTO public.site_content (section, mode, field, value) VALUES ('about', 'thor', 'panel4Kicker', '"THE CREW"'::jsonb) ON CONFLICT (section, mode, field) DO NOTHING;
INSERT INTO public.site_content (section, mode, field, value) VALUES ('about', 'thor', 'panel4Caption', '"No Pirate King sails alone. No Avenger flies solo."'::jsonb) ON CONFLICT (section, mode, field) DO NOTHING;
INSERT INTO public.site_content (section, mode, field, value) VALUES ('about', 'thor', 'panel4Body1', '"Designers, PMs, ML engineers, infra wizards — the Straw Hats of every project. Pairing with brilliant people on hard problems is the whole point. Code reviews are how we lift each other’s craft."'::jsonb) ON CONFLICT (section, mode, field) DO NOTHING;
INSERT INTO public.site_content (section, mode, field, value) VALUES ('about', 'thor', 'panel4Body2', '"Collaboration is the real superpower. Mjolnir is just the delivery mechanism. Gum-Gum-Bazooka, but for shipping features."'::jsonb) ON CONFLICT (section, mode, field) DO NOTHING;
INSERT INTO public.site_content (section, mode, field, value) VALUES ('about', 'thor', 'panel5Kicker', '"WHAT''S NEXT"'::jsonb) ON CONFLICT (section, mode, field) DO NOTHING;
INSERT INTO public.site_content (section, mode, field, value) VALUES ('about', 'thor', 'panel5Caption', '"The thunder never stops."'::jsonb) ON CONFLICT (section, mode, field) DO NOTHING;
INSERT INTO public.site_content (section, mode, field, value) VALUES ('about', 'thor', 'panel5Body1', '"Building AI-powered products where Asgardian engineering polish meets agent-grade reasoning. RAG over your data, LLM agents that ship, R3F scenes that ship, design systems that scale."'::jsonb) ON CONFLICT (section, mode, field) DO NOTHING;
INSERT INTO public.site_content (section, mode, field, value) VALUES ('about', 'thor', 'panel5Body2', '"Open to senior roles & contracts. If the challenge is worthy of Mjolnir, reach out."'::jsonb) ON CONFLICT (section, mode, field) DO NOTHING;
INSERT INTO public.site_content (section, mode, field, value) VALUES ('about', 'thor', 'burst1', '"CRUNCH!"'::jsonb) ON CONFLICT (section, mode, field) DO NOTHING;
